        auto byteOffset =
            static_cast<size_t>(view.getProperty(rt, "byteOffset").asNumber());
        // Honour byteOffset for safety (defensive; currently always 0).
        RustBuffer rb{
            .capacity = static_cast<uint64_t>(capacity),
            .len = 0,
            .data = buffer.data(rt) + byteOffset,
        };
